  created() {
    // 根据URL查询参数设置当前活动的标签页
    const tab = this.$route.query.tab;
    if (tab) {
      this.activeTab = tab;
    } else {
      this.activeTab = 'news';
    }
  },
  watch: {
    // 监听路由变化，更新活动标签页
    '$route.query.tab': function (newTab) {
      if (newTab) {
        this.activeTab = newTab;
      } else {
        this.activeTab = 'news';
      }
    }
  },
  methods: {
    handleSelect(key) {
      this.activeTab = key;

      // 修复路由导航错误
      const currentQuery = this.$route.query.tab;
      try {
        if (key === 'news') {
          if (currentQuery) {
            // 只有当需要移除查询参数时才导航
            this.$router.push({
              path: '/news-center',
              query: {}
            }).catch(err => {
              if (err.name !== 'NavigationDuplicated') {
                throw err;
              }
            });
          }
        } else if (key !== currentQuery) {
          // 只有当切换到不同的标签页时才导航
          this.$router.push({
            path: '/news-center',
            query: {
              tab: key
            }
          }).catch(err => {
            if (err.name !== 'NavigationDuplicated') {
              throw err;
            }
          });
        }
      } catch (err) {
        // 忽略导航重复错误
        if (err.name !== 'NavigationDuplicated') {
          console.error(err);
        }
      }
    },
